<template><header class="top"><div class="bar"><router-link to="/" class="logo"><b>4</b><span>VIDEO</span></router-link><nav><router-link to="/">首页</router-link><router-link v-for="c in cats.slice(0,10)" :key="c.type_id" :to="`/category/${c.type_id}`">{{c.type_name}}</router-link><router-link to="/history">历史</router-link></nav><form class="search" @submit.prevent="go"><input v-model="q" placeholder="搜索影片..."/><button>搜索</button></form><button class="menu" @click="open=!open">☰</button></div><div v-if="open" class="mobileNav"><router-link to="/" @click="open=false">首页</router-link><router-link v-for="c in cats" :key="c.type_id" :to="`/category/${c.type_id}`" @click="open=false">{{c.type_name}}</router-link></div></header></template>
<script setup>import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import {getCategories,normalizeCats} from '../api/vod';const router=useRouter(),q=ref(''),cats=ref([]),open=ref(false);onMounted(async()=>{try{cats.value=normalizeCats(await getCategories())}catch{}});function go(){if(q.value.trim())router.push({path:'/search',query:{wd:q.value.trim()}})}</script>
